  if(/AppleWebKit/.test(ua)) r.engine='WebKit';
  else if(/Gecko\//.test(ua)) r.engine='Gecko';
  else if(/Trident\//.test(ua)) r.engine='Trident';
  else if(/Blink/.test(ua)) r.engine='Blink';
  return r;
}
